import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last = history[-1][0]
    opp_last = history[-1][1]

    # Count recent cooperation
    recent = history[-10:] if n >= 10 else history
    opp_coops = sum(1 for _, o in recent if o == 'C')
    total = len(recent)

    # If opponent is largely cooperative, cooperate; if largely defecting, defect.
    if total > 0:
        coop_rate = opp_coops / total
    else:
        coop_rate = 1.0

    # Forced mutual cooperation after repeated mutual defection
    if n >= 4:
        last4 = history[-4:]
        if all(a == 'D' and b == 'D' for a, b in last4):
            return 'C'

    # If opponent just defected after long cooperation streak, occasionally forgive
    if opp_last == 'D':
        # If our last was C and opponent defected, retaliate but with some forgiveness
        if my_last == 'C':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # If we both defected, try to break cycle
        if my_last == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
    else:
        # Opponent cooperated
        if my_last == 'D' and coop_rate > 0.4:
